/** V2 阶段 B 的最终门：布局图必须以后置生成，并绑定已通过的拆解确认。 */
function validateV2LayoutStage(contract, targetInfo, stage, errors, requireFinalLayout = true, layoutInfo = {}, options = {}) {
  if (!requireFinalLayout) return;
