  if (!actualNodeIds || actualNodeIds.length === 0 || canonicalLayoutJson(actualNodeIds) !== canonicalLayoutJson(expectedNodeIds)) errors.push(`${label}.layout_annotation.layout_node_ids 必须按布局节点原顺序完整且只能来自已确认拆解`);
