    // 可选网页及摘要不能以半声明形式绕过身份关联。
    if ((Object.hasOwn(annotation, "layout_review_file") && (!nonEmptyString(annotation.layout_review_file) || !/\.html?$/i.test(annotation.layout_review_file))) || (!Object.hasOwn(annotation, "layout_review_file") && ["layout_review_sha256", "layout_review_identity_sha256"].some((key) => Object.hasOwn(annotation, key)))) errors.push(contractError(stage, contract, annotation, "布局审阅页字段不完整", { missing: "layout_annotation.layout_review_file", returnStage: "V2/PROPOSAL" }));
    if (annotation.decomposition_confirmation_id !== decompositionConfirmation?.confirmation_id) errors.push(contractError(stage, contract, annotation, "布局标注图未绑定当前已确认拆解 ID", { missing: "decomposition_confirmation_id", returnStage: "V2/PROPOSAL", rootCause: "方案缺失" }));
  }
