/** 判断值是否为普通 JSON 对象。 */
function isObject(value) { return value !== null && typeof value === "object" && !Array.isArray(value); }

/** 判断字符串是否为非空合同值。 */
function nonEmptyString(value) { return typeof value === "string" && value.trim().length > 0; }
const isString = nonEmptyString;

