  } else {
    for (const [names, text] of [
      [["vertical_order", "verticalOrder", "region_order", "regionOrder"], "HUD/规则/统计/棋盘/工具纵向顺序"],
      [["inter_region_spacing", "interRegionSpacing", "spacing"], "区域间间距"],
