      "additionalProperties": false,
      "required": [
        "characterId",
        "prefabPath",
        "prefabGuid",
        "sourceRevision",
        "updatedAt",
        "requiredRuntimeCases"
      ],
      "properties": {
        "characterId": {
          "type": "string",
          "minLength": 1
        },
        "prefabPath": {
          "type": "string",
          "pattern": "^Assets/(?!__UwtRiggingTests_)(?!.*\\/__UwtRiggingTests_)(?!/)(?!\\.\\.?(?:/|$))(?!.*(?:\\\\|//|(?:^|/)\\.\\.?(?:/|$))).+\\.prefab$"
        },
        "prefabGuid": {
          "type": "string",
          "pattern": "^[0-9a-f]{32}$"
        },
        "sourceRevision": {
          "type": "string",
          "minLength": 1
        },
        "updatedAt": {
          "type": "string",
          "format": "date-time",
          "pattern": "(?:Z|[+-][0-9]{2}:[0-9]{2})$"
        },
        "requiredRuntimeCases": {
          "type": "array",
          "minItems": 2,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          },
          "allOf": [
            {
              "contains": {
                "const": "runtime-instantiation"
              }
            },
            {
              "contains": {
                "const": "animation-playback"
              }
            }
          ]
        }
      }
    },
    "stageReview": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "stage"
      ],
      "properties": {
        "stage": {
          "enum": [
            "V1",
            "V2",
            "V3",
            "V4"
          ]
        },
        "confirmation": {
          "$ref": "#/$defs/stageConfirmation"
