        "decompositionConfirmation": {
          "$ref": "#/$defs/stageConfirmation"
        },
        "layoutConfirmation": {
          "$ref": "#/$defs/stageConfirmation"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "stage": {
                "const": "V2"
              }
            }
          },
          "then": {
            "not": {
              "required": [
                "confirmation"
              ]
            },
            "properties": {
              "decompositionConfirmation": {
                "properties": {
                  "stage": {
                    "const": "V2"
                  }
                }
              },
              "layoutConfirmation": {
                "properties": {
                  "stage": {
                    "const": "V2"
                  }
                }
              }
            }
          },
          "else": {
            "not": {
              "anyOf": [
                {
                  "required": [
                    "decompositionConfirmation"
                  ]
                },
                {
                  "required": [
                    "layoutConfirmation"
                  ]
                }
              ]
            }
          }
        },
        {
          "if": {
            "properties": {
              "stage": {
                "const": "V1"
              }
            }
          },
          "then": {
            "properties": {
              "confirmation": {
                "properties": {
                  "stage": {
                    "const": "V1"
                  }
                }
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "stage": {
                "const": "V3"
              }
            }
          },
          "then": {
            "properties": {
              "confirmation": {
                "properties": {
                  "stage": {
                    "const": "V3"
                  }
                }
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "stage": {
                "const": "V4"
              }
            }
          },
          "then": {
            "properties": {
              "confirmation": {
