        "panelId": {
          "type": "string",
          "minLength": 1
        },
        "runtimePanel": {
          "type": "boolean"
        }
      }
    },
    "renderTexture": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "enabled",
        "format",
        "resolutionPolicy"
      ],
      "properties": {
        "enabled": {
          "type": "boolean"
        },
        "format": {
          "type": "string",
          "minLength": 1
        },
        "resolutionPolicy": {
          "type": "string",
          "minLength": 1
        }
      }
    },
    "canvasScaler": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "status"
      ],
      "properties": {
        "status": {
          "enum": [
            "configured",
            "not-applicable"
          ]
        },
        "reason": {
          "type": "string",
          "minLength": 1
        },
        "enabled": {
          "type": "boolean"
        },
        "mode": {
          "type": "string",
          "minLength": 1
        },
        "screenMatchMode": {
          "type": "string",
          "minLength": 1
        },
        "referenceResolution": {
          "$ref": "#/$defs/positiveSize"
        },
        "matchWidthOrHeight": {
          "type": "number",
          "minimum": 0,
          "maximum": 1
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "status": {
                "const": "configured"
              }
            }
          },
          "then": {
            "required": [
              "enabled",
              "mode",
              "referenceResolution",
              "matchWidthOrHeight"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "status": {
                "const": "not-applicable"
              }
            }
          },
          "then": {
            "required": [
              "reason"
            ]
          }
        }
      ]
    },
    "panelSettings": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "status"
      ],
      "properties": {
        "status": {
          "enum": [
            "configured",
            "not-applicable"
          ]
        },
        "reason": {
          "type": "string",
          "minLength": 1
        },
        "enabled": {
          "type": "boolean"
        },
        "scaleMode": {
          "type": "string",
          "minLength": 1
        },
        "screenMatchMode": {
          "type": "string",
          "minLength": 1
        },
        "match": {
          "type": "number",
          "minimum": 0,
          "maximum": 1
        },
        "referenceResolution": {
          "$ref": "#/$defs/positiveSize"
        },
        "referenceDpi": {
          "type": "number",
          "exclusiveMinimum": 0
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "status": {
                "const": "configured"
              }
            }
          },
          "then": {
            "required": [
              "enabled",
              "scaleMode",
              "referenceResolution",
              "referenceDpi"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "status": {
                "const": "not-applicable"
              }
            }
          },
          "then": {
            "required": [
              "reason"
            ]
          }
        }
      ]
    },
    "camera": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "renderMode",
        "viewport",
        "projection",
        "measuredAtRuntime"
      ],
      "properties": {
        "id": {
          "type": "string",
          "minLength": 1
        },
        "renderMode": {
          "type": "string",
          "minLength": 1
        },
        "viewport": {
          "$ref": "#/$defs/positiveSize"
        },
        "projection": {
          "type": "string",
          "minLength": 1
        },
        "measuredAtRuntime": {
          "const": true
        }
      }
    },
    "safeArea": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "source",
        "policy",
        "measuredAtRuntime"
      ],
      "properties": {
        "source": {
          "const": "Screen.safeArea"
        },
        "policy": {
          "type": "string",
          "minLength": 1
        },
        "measuredAtRuntime": {
          "const": true
        }
      }
    },
    "inputCoordinates": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "inputSystem",
        "eventSystem",
        "screenToLocal",
        "cameraRaycast"
      ],
      "properties": {
        "inputSystem": {
          "const": "InputSystem"
        },
        "eventSystem": {
          "const": "EventSystem"
        },
        "screenToLocal": {
          "type": "string",
          "minLength": 1
        },
        "cameraRaycast": {
          "type": "string",
          "minLength": 1
        }
      }
    },
    "resize": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "mode",
        "events",
        "sameProcess"
      ],
      "properties": {
        "mode": {
          "type": "string",
          "minLength": 1
        },
        "events": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "sameProcess": {
          "const": true
        }
      }
    },
    "orientation": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "supported",
        "runtimeReflow"
      ],
      "properties": {
        "supported": {
          "type": "array",
          "minItems": 1,
          "items": {
            "enum": [
              "portrait",
              "landscape",
              "auto"
            ]
          }
        },
        "runtimeReflow": {
          "const": true
        }
      }
    },
    "localePolicy": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "singleLine",
        "wrap",
        "truncation"
      ],
      "properties": {
        "singleLine": {
          "type": "boolean"
        },
        "wrap": {
          "type": "boolean"
        },
        "truncation": {
          "const": "forbidden"
        }
      }
    },
    "textLocalization": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "programmatic"
      ],
      "properties": {
        "programmatic": {
          "type": "boolean"
        },
        "locales": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "pattern": "^[A-Za-z]{2,8}(-[A-Za-z0-9]{1,8})*$"
          }
        },
        "localePolicies": {
          "type": "object",
          "additionalProperties": {
            "$ref": "#/$defs/localePolicy"
          },
          "propertyNames": {
            "pattern": "^[A-Za-z]{2,8}(-[A-Za-z0-9]{1,8})*$"
          }
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "programmatic": {
                "const": true
              }
            }
          },
          "then": {
            "required": [
              "locales",
              "localePolicies"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "programmatic": {
                "const": false
              }
            }
          },
          "then": {
            "not": {
              "anyOf": [
                {
                  "required": [
                    "locales"
                  ]
                },
                {
                  "required": [
                    "localePolicies"
                  ]
                }
              ]
            }
          }
        }
      ]
    },
    "resourceResolution": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "sourceScale",
        "runtimeScalePolicy",
        "platformMeasured"
      ],
      "properties": {
        "sourceScale": {
          "type": "number",
          "exclusiveMinimum": 0
        },
        "runtimeScalePolicy": {
          "type": "string",
          "minLength": 1
        },
        "platformMeasured": {
          "const": true
        },
        "override": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "reason"
          ],
          "properties": {
            "reason": {
              "type": "string",
              "minLength": 1
            },
            "approvalRef": {
              "type": "string",
              "minLength": 1
            },
            "evidenceRef": {
              "type": "string",
              "minLength": 1
            }
          },
          "anyOf": [
            {
              "required": [
                "approvalRef"
              ]
            },
            {
              "required": [
                "evidenceRef"
              ]
            }
          ]
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "sourceScale": {
                "not": {
                  "const": 1
                }
              }
            }
          },
          "then": {
            "required": [
              "override"
            ]
          }
        }
      ]
    },
    "performanceBudget": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "frameTimeMs",
        "uiDrawCalls",
        "renderTexturePixels",
        "memoryMb",
        "degradationPolicy"
      ],
      "properties": {
        "frameTimeMs": {
          "type": "number",
          "minimum": 0
        },
        "uiDrawCalls": {
          "type": "number",
          "minimum": 0
        },
        "renderTexturePixels": {
          "type": "number",
          "minimum": 0
        },
        "memoryMb": {
          "type": "number",
          "minimum": 0
        },
        "degradationPolicy": {
          "type": "string",
          "minLength": 1
        }
      }
    },
    "representativeViewport": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "width",
        "height",
        "orientation"
      ],
      "properties": {
        "id": {
          "type": "string",
          "minLength": 1
        },
        "width": {
          "type": "integer",
          "minimum": 1
        },
        "height": {
          "type": "integer",
          "minimum": 1
        },
        "orientation": {
          "enum": [
            "portrait",
            "landscape",
            "square"
          ]
        }
      }
    },
    "approval": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "approvalId",
        "workItemId",
        "baselineHash",
        "stageId",
        "actionType",
        "actionLevel",
        "gate",
        "object",
        "impact",
        "target",
        "approvedAt",
        "approvedBy"
      ],
      "properties": {
        "approvalId": {
          "type": "string",
          "minLength": 1
        },
        "workItemId": {
          "type": "string",
          "minLength": 1
        },
        "baselineHash": {
          "type": "string",
          "minLength": 1
        },
        "stageId": {
          "type": "string",
          "minLength": 1
        },
        "actionLevel": {
          "enum": [
            "A4",
            "A5",
            "A6"
          ]
        },
        "gate": {
          "const": "F4"
        },
        "actionType": {
          "type": "string",
          "pattern": "^unity-[a-z0-9-]+$"
        },
        "object": {
          "type": "string",
          "minLength": 1
        },
        "impact": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "target": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "approvedAt": {
          "type": "string",
          "minLength": 1
        },
        "approvedBy": {
          "type": "string",
          "minLength": 1
        }
      }
    },
    "pendingApproval": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "approvalId",
        "workItemId",
        "baselineHash",
        "stageId",
        "actionType",
        "actionLevel",
        "gate",
        "object",
        "impact",
        "target"
      ],
      "properties": {
        "approvalId": {
          "type": "string",
          "minLength": 1
        },
        "workItemId": {
          "type": "string",
          "minLength": 1
        },
        "baselineHash": {
          "type": "string",
          "minLength": 1
        },
        "stageId": {
          "type": "string",
          "minLength": 1
        },
        "actionLevel": {
          "enum": [
            "A4",
            "A5",
            "A6"
          ]
        },
        "gate": {
          "const": "F4"
        },
        "actionType": {
          "type": "string",
          "pattern": "^unity-[a-z0-9-]+$"
        },
        "object": {
          "type": "string",
          "minLength": 1
        },
        "impact": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "target": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "returnRecord": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "classification",
        "reason",
        "affectedScope",
        "fromState",
        "toState",
        "recordedAt",
        "returnState",
        "invalidatedArtifacts",
        "invalidatedReferences"
      ],
      "properties": {
        "classification": {
          "enum": [
            "upstream-fact-invalidated",
            "scope-changed",
            "hard-gate-would-be-bypassed"
          ]
        },
        "reason": {
          "type": "string",
          "minLength": 1
        },
        "affectedScope": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1,
            "pattern": "^(stage|scene|artifact):[^\\s*?]+$"
          },
          "uniqueItems": true
        },
        "fromState": {
          "type": "string",
          "minLength": 1
        },
        "toState": {
          "const": "RETURN"
        },
        "recordedAt": {
          "type": "string",
          "minLength": 1,
          "format": "date-time"
        },
        "resolvedAt": {
          "type": [
            "string",
            "null"
          ]
        },
        "returnState": {
          "enum": [
            "BASELINE",
            "PROPOSAL",
            "REVIEW",
            "IMPLEMENTING"
          ]
        },
        "priorInvalidatedReferences": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/returnRecord/properties/invalidatedReferences"
          }
        },
        "invalidatedReferences": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "implementationPackagePath",
            "evidenceManifestPath",
            "packageId",
            "evidenceId",
            "planVersion"
          ],
          "properties": {
            "implementationPackagePath": {
              "type": [
                "string",
                "null"
              ],
              "minLength": 1
            },
            "evidenceManifestPath": {
              "type": [
                "string",
                "null"
              ],
              "minLength": 1
            },
            "packageId": {
              "type": [
                "string",
                "null"
              ],
              "minLength": 1
            },
            "evidenceId": {
              "type": [
                "string",
                "null"
              ],
              "minLength": 1
            },
            "planVersion": {
              "type": [
                "string",
                "null"
              ],
              "minLength": 1
            }
          }
        },
        "invalidatedArtifacts": {
          "type": "array",
          "minItems": 4,
          "maxItems": 4,
          "uniqueItems": true,
          "items": {
            "enum": [
              "implementationPackage",
              "executionState",
              "evidenceManifest",
              "approval"
            ]
          }
        }
      }
    }
  }
